package com.sunantongsan.novastriker;

import android.webkit.JavascriptInterface;
import com.android.billingclient.api.*;
import org.json.*;
import java.util.*;

/** Play owns purchase tokens; only the authenticated server can credit the wallet. */
final class NovaBilling implements PurchasesUpdatedListener {
    private static final String[] IDS={"nova_5000","nova_10500","nova_19000","nova_40000","nova_85000","nova_180000"};
    private final MainActivity activity;
    private final NovaCloud cloud;
    private final BillingClient client;
    private final Set<String> verifying=Collections.synchronizedSet(new HashSet<>());
    private boolean closed,connecting,buying;
    private String account="";
    NovaBilling(MainActivity activity,NovaCloud cloud){this.activity=activity;this.cloud=cloud;client=BillingClient.newBuilder(activity).setListener(this).enablePendingPurchases(PendingPurchasesParams.newBuilder().enableOneTimeProducts().build()).enableAutoServiceReconnection().build();}
    private void emit(String event,JSONObject data){activity.runOnUiThread(()->{if(!closed)activity.billingEvent348(event,data);});}
    private void message(String text){try{emit("status",new JSONObject().put("message",text));}catch(JSONException ignored){}}
    private void connect(Runnable next){if(closed)return;if(client.isReady()){next.run();return;}if(connecting){buying=false;message("กำลังเชื่อมต่อ Google Play");return;}connecting=true;client.startConnection(new BillingClientStateListener(){public void onBillingSetupFinished(BillingResult r){connecting=false;if(r.getResponseCode()==BillingClient.BillingResponseCode.OK)next.run();else {buying=false;message("Google Play ยังไม่พร้อม กรุณาลองใหม่");}}public void onBillingServiceDisconnected(){connecting=false;}});}
    private void authorized(Runnable next,boolean silent){cloud.billing348(new JSONObject(),(data,error)->{if(closed)return;if(error!=null||data==null||!data.optBoolean("ready")){buying=false;if(!silent)message("ยังไม่ได้เปิดการซื้อทดสอบ Google Play สำหรับบัญชีนี้");return;}account=data.optString("account");if(account.matches("[0-9a-f]{64}"))connect(next);});}
    private void query(String only,java.util.function.Consumer<List<ProductDetails>> done){List<QueryProductDetailsParams.Product> products=new ArrayList<>();for(String id:IDS)if(only==null||id.equals(only))products.add(QueryProductDetailsParams.Product.newBuilder().setProductId(id).setProductType(BillingClient.ProductType.INAPP).build());client.queryProductDetailsAsync(QueryProductDetailsParams.newBuilder().setProductList(products).build(),(result,details)->{if(result.getResponseCode()!=BillingClient.BillingResponseCode.OK){buying=false;message("โหลดแพ็กเกจจาก Google Play ไม่สำเร็จ");return;}done.accept(details.getProductDetailsList());});}
    @JavascriptInterface public void catalog(){activity.runOnUiThread(()->authorized(()->query(null,list->{JSONArray products=new JSONArray();for(ProductDetails p:list){List<ProductDetails.OneTimePurchaseOfferDetails> offers=p.getOneTimePurchaseOfferDetailsList();if(offers==null||offers.isEmpty())continue;try{products.put(new JSONObject().put("id",p.getProductId()).put("price",offers.get(0).getFormattedPrice()));}catch(JSONException ignored){}}try{emit("catalog",new JSONObject().put("products",products).put("message",products.length()==0?"แพ็กเกจยังไม่พร้อมใน Google Play":"ใช้บัตรทดสอบของ Google Play เท่านั้น"));}catch(JSONException ignored){}restoreReady();}),false));}
    @JavascriptInterface public void buy(String product){if(!Arrays.asList(IDS).contains(product))return;activity.runOnUiThread(()->{if(buying||closed)return;buying=true;authorized(()->query(product,list->{if(list.isEmpty()){buying=false;message("แพ็กเกจยังไม่พร้อมใน Google Play");return;}ProductDetails p=list.get(0);List<ProductDetails.OneTimePurchaseOfferDetails> offers=p.getOneTimePurchaseOfferDetailsList();if(offers==null||offers.isEmpty()){buying=false;message("ไม่พบราคาสินค้า");return;}activity.runOnUiThread(()->new android.app.AlertDialog.Builder(activity).setTitle("Google Play · ซื้อทดสอบ").setMessage("เลือกบัตรทดสอบเท่านั้น หากหน้าชำระเงินไม่ระบุว่าเป็นการทดสอบ ให้ยกเลิก").setNegativeButton("ยกเลิก",(dialog,which)->{buying=false;message("ยกเลิกแล้ว");}).setOnCancelListener(dialog->{buying=false;message("ยกเลิกแล้ว");}).setPositiveButton("ดำเนินการ",(dialog,which)->{BillingFlowParams.ProductDetailsParams item=BillingFlowParams.ProductDetailsParams.newBuilder().setProductDetails(p).setOfferToken(offers.get(0).getOfferToken()).build();BillingResult r=client.launchBillingFlow(activity,BillingFlowParams.newBuilder().setObfuscatedAccountId(account).setProductDetailsParamsList(Collections.singletonList(item)).build());if(r.getResponseCode()!=BillingClient.BillingResponseCode.OK){buying=false;message("เปิดหน้าซื้อไม่สำเร็จ กรุณาลองใหม่");}}).show());}),false);});}
    @Override public void onPurchasesUpdated(BillingResult result,List<Purchase> purchases){buying=false;if(result.getResponseCode()==BillingClient.BillingResponseCode.USER_CANCELED){message("ยกเลิกแล้ว");return;}if(result.getResponseCode()!=BillingClient.BillingResponseCode.OK){message("การซื้อยังไม่สำเร็จ กรุณาตรวจใน Google Play");return;}if(purchases!=null)for(Purchase p:purchases)verify(p);}
    private void verify(Purchase p){if(closed)return;if(p.getPurchaseState()==Purchase.PurchaseState.PENDING){message("รอ Google Play ยืนยันการชำระเงิน");return;}if(p.getPurchaseState()!=Purchase.PurchaseState.PURCHASED||p.getProducts().size()!=1)return;String product=p.getProducts().get(0);if(!Arrays.asList(IDS).contains(product)||!verifying.add(p.getPurchaseToken()))return;try{JSONObject body=new JSONObject().put("action","verify").put("product",product).put("token",p.getPurchaseToken());cloud.billing348(body,(data,error)->{verifying.remove(p.getPurchaseToken());if(error!=null||data==null){message("รอตรวจใบเสร็จ เปิดร้านอีกครั้งเพื่อลองใหม่");return;}emit("granted",data);});}catch(JSONException ignored){verifying.remove(p.getPurchaseToken());}}
    private void restoreReady(){client.queryPurchasesAsync(QueryPurchasesParams.newBuilder().setProductType(BillingClient.ProductType.INAPP).build(),(r,list)->{if(r.getResponseCode()==BillingClient.BillingResponseCode.OK)for(Purchase p:list)verify(p);});}
    void resume(){activity.runOnUiThread(()->authorized(this::restoreReady,true));}
    void destroy(){closed=true;client.endConnection();}
}
